// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        uint256 bounded = bound(amount, 0, 1 ether);

        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent);

        vm.deal(caller, 1 ether);

        bool ok;
        vm.prank(caller);
        try c.sendMoney(address(0x1234), bounded) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(!ok);
        } else {
            assertTrue(address(c).balance <= 1 ether);
        }
    }
}
